### Task 2: Auth — login, token storage, protected routes

**Files:**
- Create: `dashboard/src/auth/AuthContext.tsx`, `dashboard/src/auth/LoginPage.tsx`, `dashboard/src/auth/ProtectedRoute.tsx`
- Modify: `dashboard/src/App.tsx`, `dashboard/package.json` (add `react-router-dom`)

**Interfaces:**
- Produces: `AuthProvider`, `useAuth()`, `LoginPage`, `ProtectedRoute`.
- Consumes: none yet (Task 2 talks to the backend directly via `fetch`, not through the API client — Task 3 builds the client `AuthContext` will be refactored to use once it exists. Keep this task's backend calls as plain `fetch` calls against `POST /api/v1/auth/login`, `POST /api/v1/auth/refresh`, `GET /api/v1/auth/me`, reading `import.meta.env.VITE_API_BASE_URL` directly).

- [ ] **Step 1: Install the router**

```bash
cd /Users/taha/Documents/atlas-fieldforce/dashboard
npm install react-router-dom
```

- [ ] **Step 2: Write `src/auth/AuthContext.tsx`**

```tsx
import { createContext, useContext, useEffect, useState, type ReactNode } from 'react'

const API_BASE = import.meta.env.VITE_API_BASE_URL as string
const REFRESH_TOKEN_KEY = 'atlas_refresh_token'

export interface AuthUser {
  id: string
  email: string
  role: string
}

interface TokenPair {
  access_token: string
  refresh_token: string
}

interface AuthContextValue {
  user: AuthUser | null
  accessToken: string | null
  isLoading: boolean
  login: (tenantId: string, email: string, password: string) => Promise<void>
  logout: () => void
}

const AuthContext = createContext<AuthContextValue | null>(null)

async function fetchMe(accessToken: string): Promise<AuthUser> {
  const response = await fetch(`${API_BASE}/api/v1/auth/me`, {
    headers: { Authorization: `Bearer ${accessToken}` },
  })
  if (!response.ok) throw new Error('failed to fetch current user')
  return response.json()
}

async function refreshTokens(refreshToken: string): Promise<TokenPair> {
  const response = await fetch(`${API_BASE}/api/v1/auth/refresh`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ refresh_token: refreshToken }),
  })
  if (!response.ok) throw new Error('refresh failed')
  return response.json()
}

export function AuthProvider({ children }: { children: ReactNode }) {
  const [user, setUser] = useState<AuthUser | null>(null)
  const [accessToken, setAccessToken] = useState<string | null>(null)
  const [isLoading, setIsLoading] = useState(true)

  useEffect(() => {
    const storedRefreshToken = localStorage.getItem(REFRESH_TOKEN_KEY)
    if (!storedRefreshToken) {
      setIsLoading(false)
      return
    }
    refreshTokens(storedRefreshToken)
      .then(async (tokens) => {
        const me = await fetchMe(tokens.access_token)
        if (me.role !== 'manager') {
          localStorage.removeItem(REFRESH_TOKEN_KEY)
          setIsLoading(false)
          return
        }
        localStorage.setItem(REFRESH_TOKEN_KEY, tokens.refresh_token)
        setAccessToken(tokens.access_token)
        setUser(me)
        setIsLoading(false)
      })
      .catch(() => {
        localStorage.removeItem(REFRESH_TOKEN_KEY)
        setIsLoading(false)
      })
  }, [])

  async function login(tenantId: string, email: string, password: string) {
    const response = await fetch(`${API_BASE}/api/v1/auth/login`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'X-Tenant-Id': tenantId },
      body: JSON.stringify({ email, password }),
    })
    if (!response.ok) throw new Error('invalid credentials')
    const tokens: TokenPair = await response.json()
    const me = await fetchMe(tokens.access_token)
    if (me.role !== 'manager') {
      throw new Error('this dashboard is for managers')
    }
    localStorage.setItem(REFRESH_TOKEN_KEY, tokens.refresh_token)
    setAccessToken(tokens.access_token)
    setUser(me)
  }

  function logout() {
    localStorage.removeItem(REFRESH_TOKEN_KEY)
    setAccessToken(null)
    setUser(null)
  }

  return (
    <AuthContext.Provider value={{ user, accessToken, isLoading, login, logout }}>
      {children}
    </AuthContext.Provider>
  )
}

export function useAuth(): AuthContextValue {
  const ctx = useContext(AuthContext)
  if (!ctx) throw new Error('useAuth must be used within an AuthProvider')
  return ctx
}
```

- [ ] **Step 3: Write `src/auth/LoginPage.tsx`**

A form with three fields (tenant ID, email, password), calling `useAuth().login(...)` on submit, showing the thrown error message on failure, and navigating to `/` on success. Implementer's discretion on exact markup/Tailwind classes — keep it simple, one column, centered card, matches the placeholder styling already in `App.tsx`. Note in the tenant-ID field's label or placeholder that it's a raw UUID (e.g. placeholder text `"Tenant ID (UUID)"`) so it's not mistaken for a company name field.

- [ ] **Step 4: Write `src/auth/ProtectedRoute.tsx`**

```tsx
import { Navigate } from 'react-router-dom'
import type { ReactNode } from 'react'
import { useAuth } from './AuthContext'

export function ProtectedRoute({ children }: { children: ReactNode }) {
  const { user, isLoading } = useAuth()
  if (isLoading) return <div className="p-8 text-gray-500">Loading…</div>
  if (!user) return <Navigate to="/login" replace />
  return <>{children}</>
}
```

- [ ] **Step 5: Wire routing into `src/App.tsx`**

```tsx
import { BrowserRouter, Routes, Route } from 'react-router-dom'
import { AuthProvider } from './auth/AuthContext'
import { LoginPage } from './auth/LoginPage'
import { ProtectedRoute } from './auth/ProtectedRoute'

function Home() {
  return (
    <div className="min-h-screen bg-gray-50 p-8">
      <h1 className="text-2xl font-semibold text-gray-900">Atlas Field Force — Manager Dashboard</h1>
    </div>
  )
}

function App() {
  return (
    <AuthProvider>
      <BrowserRouter>
        <Routes>
          <Route path="/login" element={<LoginPage />} />
          <Route path="/" element={<ProtectedRoute><Home /></ProtectedRoute>} />
        </Routes>
      </BrowserRouter>
    </AuthProvider>
  )
}

export default App
```

(`Home` here is a placeholder — Task 4 replaces it with `MapView`.)

